// Some portions generated by Claude Code
package org.eclipse.rdf4j.workbench.base;

import static org.assertj.core.api.Assertions.assertThat;

import java.nio.file.Path;

import javax.xml.parsers.DocumentBuilderFactory;

import org.junit.jupiter.api.Test;
import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.w3c.dom.NodeList;

/**
 * The WAR loads the Workbench gateway when the application starts, as the Spring Boot runner does, so that its policy
 * file is validated then rather than on the first request.
 */
class WorkbenchDeploymentDescriptorTest {

	@Test
	void theWorkbenchServletIsLoadedOnStartup() throws Exception {
		DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
		factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
		Document descriptor = factory.newDocumentBuilder()
				.parse(Path.of("src/main/webapp/WEB-INF/web.xml").toFile());

		NodeList servlets = descriptor.getElementsByTagName("servlet");
		String loadOnStartup = null;
		for (int index = 0; index < servlets.getLength(); index++) {
			Element servlet = (Element) servlets.item(index);
			String name = servlet.getElementsByTagName("servlet-name").item(0).getTextContent().trim();
			if ("workbench".equals(name)) {
				NodeList load = servlet.getElementsByTagName("load-on-startup");
				loadOnStartup = load.getLength() == 0 ? null : load.item(0).getTextContent().trim();
			}
		}

		assertThat(loadOnStartup).as("load-on-startup of the workbench servlet").isNotNull();
		assertThat(Integer.parseInt(loadOnStartup)).isGreaterThanOrEqualTo(0);
	}
}
